<?php
session_start();include('dbstring.php');include('check-login.php');include_once('user-management-utils.php');include_once('alumni-utils.php');if(!um_is_admin_manager()){header('location:index.php');exit();}alumni_ensure_tables($con);$message='';
if(isset($_POST['hide_message'])&&alumni_csrf_valid($_POST['csrf']??'')){$id=(int)$_POST['messageid'];mysqli_query($con,"UPDATE tblalumnichatmessage SET chathidden=1 WHERE messageid=$id");$message='Message hidden from alumni conversations.';}
if(isset($_POST['show_message'])&&alumni_csrf_valid($_POST['csrf']??'')){$id=(int)$_POST['messageid'];mysqli_query($con,"UPDATE tblalumnichatmessage SET chathidden=0 WHERE messageid=$id");$message='Message restored.';}
$messages=mysqli_query($con,"SELECT c.*,a.fullname FROM tblalumnichatmessage c JOIN tblalumni a ON a.alumniid=c.alumniid ORDER BY c.createdat DESC LIMIT 150");
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alumni Chat Moderation</title><style>body{font:16px Arial;background:#f4f7fb;color:#172b4d;margin:0}.wrap{max-width:980px;margin:32px auto;padding:0 18px}.top{display:flex;justify-content:space-between;gap:12px}.card{background:#fff;border:1px solid #dce5ed;border-radius:12px;padding:18px;margin-top:15px}.hidden{opacity:.55;background:#f8fafc}.msg{border-bottom:1px solid #e6edf4;padding:14px 0}.msg:last-child{border:0}.meta{font-size:12px;color:#64748b}button,a{padding:9px 12px;border:0;border-radius:6px;background:#08766f;color:#fff;font-weight:bold;text-decoration:none}.hide{background:#b42318}.show{background:#08766f}.notice{background:#e5f7ef;padding:12px;border-radius:7px}</style></head><body><main class="wrap"><div class="top"><div><h1>Alumni chat moderation</h1><p>Review and hide unsuitable messages. Hidden messages remain in the audit record.</p></div><a href="alumni-hub.php">Alumni Hub</a></div><?php if($message){?><p class="notice"><?php echo alumni_safe($message);?></p><?php }?><section class="card"><?php while($messages&&($row=mysqli_fetch_assoc($messages))){?><article class="msg<?php echo $row['chathidden']?' hidden':'';?>"><b><?php echo alumni_safe($row['fullname']);?></b> <span class="meta">· <?php echo alumni_safe($row['chatroom']);?> · <?php echo alumni_safe($row['createdat']);?></span><p><?php echo nl2br(alumni_safe($row['messagebody']));?></p><form method="post"><input type="hidden" name="csrf" value="<?php echo alumni_safe(alumni_csrf_token());?>"><input type="hidden" name="messageid" value="<?php echo (int)$row['messageid'];?>"><?php if($row['chathidden']){?><button class="show" name="show_message">Restore message</button><?php }else{?><button class="hide" name="hide_message">Hide message</button><?php }?></form></article><?php }?></section></main></body></html>
